const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry definitions
  const deathValley = ee.Geometry.Point(-116.9325, 36.5323).buffer(5000); // 5km buffer
  const world = ee.Geometry.Rectangle([-180, -60, 180, 80]); // Exclude Antarctica

  // 2. Time range
  const startDate = '2004-01-01';
  const endDate = '2004-12-31';

  // 3. Data acquisition - MODIS Monthly LST (MOD11C3)
  let collection = ee.ImageCollection('MODIS/061/MOD11C3')
    .filterDate(startDate, endDate)
    .select(['LST_Day_CMG', 'QC_Day']);

  // Check if collection has data
  const collectionSize = collection.size().getInfo();
  console.log(`2004 MODIS Monthly Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No monthly data found, trying daily product...");
    // Fallback to MODIS Daily (MOD11A1) with monthly max composite
    collection = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(startDate, endDate)
      .select(['LST_Day_1km', 'QC_Day']);

    const dailySize = collection.size().getInfo();
    console.log(`2004 MODIS Daily Images: ${dailySize}`);

    if (dailySize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }

    // Create monthly max composites from daily data
    const months = ee.List.sequence(1, 12);
    collection = ee.ImageCollection.fromImages(
      months.map(function(m) {
        const start = ee.Date(startDate).advance(m.subtract(1), 'month');
        const end = start.advance(1, 'month');
        return collection
          .filterDate(start, end)
          .max()
          .set('system:time_start', start.millis());
      })
    );
  }

  // 4. Processing function
  const processImage = function(image) {
    // Get LST band (scale 0.02 for Kelvin conversion)
    const lst = image.select(['LST_Day', 'LST_Day_1km', 'LST_Day_CMG']).reduce(ee.Reducer.firstNonNull());

    // Convert to Celsius: (DN * 0.02) - 273.15
    const lstCelsius = lst.multiply(0.02).subtract(273.15);

    // Create QC mask if QC band exists
    const qc = image.select(['QC_Day', 'QC']).reduce(ee.Reducer.firstNonNull());
    let mask = ee.Image(1);

    // Simple QC check: bits 0-1 = 00 (LST produced, good quality)
    if (qc) {
      mask = qc.bitwiseAnd(3).eq(0);
    }

    return lstCelsius.updateMask(mask).rename('LST_C');
  };

  const processedCol = collection.map(processImage);

  // 5. Get Death Valley maximum
  const dvMaxImage = processedCol.max();
  const dvMax = dvMaxImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: deathValley,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C');

  // 6. Get global maximum (with coarser scale for performance)
  const globalMaxImage = processedCol.max();
  const globalMax = globalMaxImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: world,
    scale: 50000,  // 50km scale for global computation
    maxPixels: 1e9
  }).get('LST_C');

  // 7. Get pixel counts for validation
  const dvCount = dvMaxImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: deathValley,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_C');

  const globalCount = globalMaxImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: world,
    scale: 50000,
    maxPixels: 1e9
  }).get('LST_C');

  // 8. Retrieve values
  const [dvMaxVal, globalMaxVal, dvCountVal, globalCountVal] = await Promise.all([
    ee.Number(dvMax).getInfo(),
    ee.Number(globalMax).getInfo(),
    ee.Number(dvCount).getInfo(),
    ee.Number(globalCount).getInfo()
  ]);

  console.log(`Death Valley Max LST: ${dvMaxVal !== null ? dvMaxVal.toFixed(2) : 'null'}°C`);
  console.log(`Global Max LST: ${globalMaxVal !== null ? globalMaxVal.toFixed(2) : 'null'}°C`);
  console.log(`Death Valley Valid Pixels: ${dvCountVal}`);
  console.log(`Global Valid Pixels: ${globalCountVal}`);

  // 9. Validate results
  if (dvCountVal === 0 || globalCountVal === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (dvMaxVal === null || globalMaxVal === null || 
      isNaN(dvMaxVal) || isNaN(globalMaxVal) ||
      dvMaxVal > 100 || dvMaxVal < -100 ||  // Sanity check for LST
      globalMaxVal > 100 || globalMaxVal < -100) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 10. Determine answer
  // If Death Valley's max is within 0.5°C of global max (accounting for scale differences)
  if (dvMaxVal >= globalMaxVal - 0.5) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
